</style></head><body>
<div class="wrap">
<header><div><h1>AI for Social Good · Project Radar</h1><div class="sub" id="meta"></div></div>
<div class="sub"><a href="?format=json" style="color:var(--text2)">JSON</a></div></header>
<section class="grid kpis" id="kpis"></section>
<section class="grid two" style="margin-top:16px">
  <div class="card"><h2>Projects by impact domain · click to filter</h2><div class="bars" id="domain"></div></div>
  <div class="card"><h2>New items per week, by source (last 12 weeks)</h2><div class="legend" id="wlegend"></div><div id="weekly"></div></div>
  <div class="card"><h2>UN SDGs addressed</h2><div class="bars" id="sdg"></div></div>
  <div class="card"><h2>Region</h2><div class="bars" id="region"></div></div>
</section>
<section class="card" style="margin-top:16px">
  <h2>Project catalogue</h2>
  <div class="filters"><input id="q" placeholder="Search title, summary, owner…">
  <select id="fsrc"><option value="">All sources</option></select><select id="fdom"><option value="">All domains</option></select>
  <button id="reset">Reset</button></div>
  <p class="count" id="count"></p>
  <div class="tscroll"><table class="tbl"><thead><tr><th>Project</th><th class="hide-sm">Domain / SDG</th><th class="hide-sm">Region</th><th>Date</th></tr></thead><tbody id="rows"></tbody></table></div>
  <div style="text-align:center;margin-top:12px"><button id="more" style="display:none">Show more</button></div>
</section>
</div><div id="tip"></div>
<script>
const D = ${payload};
const SRC = {github:{label:'GitHub',v:'--s1'},arxiv:{label:'arXiv',v:'--s2'},news:{label:'News',v:'--s3'}};
const DOM = {global_health:'Global health',agriculture_food:'Agriculture & food',education:'Education',financial_inclusion:'Financial inclusion',gender_equality:'Gender equality',water_sanitation:'Water & sanitation',climate_environment:'Climate & environment',disaster_humanitarian:'Disaster & humanitarian',accessibility:'Accessibility',governance_rights:'Governance & rights',general:'General / other'};
const SDG = {1:'No poverty',2:'Zero hunger',3:'Good health',4:'Quality education',5:'Gender equality',6:'Clean water',7:'Clean energy',8:'Decent work',9:'Industry & innovation',10:'Reduced inequalities',11:'Sustainable cities',12:'Responsible consumption',13:'Climate action',14:'Life below water',15:'Life on land',16:'Peace & justice',17:'Partnerships'};
const $ = (id) => document.getElementById(id);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const fmtDate = (d) => d ? new Date(d).toISOString().slice(0,10) : '';
const tip = $('tip');
const showTip = (e, html) => { tip.innerHTML = html; tip.style.display = 'block'; tip.style.left = Math.min(e.clientX + 12, innerWidth - 220) + 'px'; tip.style.top = (e.clientY + 12) + 'px'; };
const hideTip = () => { tip.style.display = 'none'; };

const run = D.lastRun;
$('meta').textContent = 'Updated ' + (D.generatedAt ? new Date(D.generatedAt).toLocaleString() : '—') + (run ? ' · last collection ' + new Date(run.started_at).toLocaleString() + ' (' + run.fetched + ' fetched, ' + run.new_items + ' new)' : ' · no collection run yet');

const srcLine = (D.bySource || []).map((s) => (SRC[s.k]?.label || s.k) + ' ' + s.n).join(' · ') || '—';
$('kpis').innerHTML = [
  ['Relevant projects', D.total ?? 0, srcLine],
  ['New in last 7 days', D.new7d ?? 0, 'first seen by the collector'],
  ['Impact domains covered', (D.byDomain || []).filter((d) => d.k !== 'general').length, 'of 10 tracked domains'],
  ['Classified by LLM', (D.llmShare ?? 0) + '%', 'the rest by keyword rules'],
].map(([l, v, d]) => '<div class="card kpi"><div class="l">' + l + '</div><div class="v">' + v + '</div><div class="d">' + esc(d) + '</div></div>').join('');

let domFilter = '';
function bars(el, list, label, onClick) {
  const max = Math.max(1, ...list.map((x) => x.n));
  el.innerHTML = list.length ? list.map((x) => '<div class="bar' + (onClick && domFilter === x.k ? ' on' : '') + '" data-k="' + esc(x.k) + '"><span class="k" title="' + esc(label(x.k)) + '">' + esc(label(x.k)) + '</span><span class="t"><span class="f" style="display:block;width:' + (100 * x.n / max) + '%"></span></span><span class="n">' + x.n + '</span></div>').join('') : '<div class="muted">No data yet</div>';
  el.querySelectorAll('.bar').forEach((b) => {
    const x = list.find((i) => String(i.k) === b.dataset.k);
    b.onmousemove = (e) => showTip(e, '<b>' + esc(label(x.k)) + '</b><br>' + x.n + ' projects');
    b.onmouseleave = hideTip;
    if (onClick) b.onclick = () => onClick(x.k);
  });
}
const drawDomains = () => bars($('domain'), D.byDomain || [], (k) => DOM[k] || k, (k) => { domFilter = domFilter === k ? '' : k; $('fdom').value = domFilter; drawDomains(); table(); });
drawDomains();
bars($('sdg'), (D.bySdg || []).slice().sort((a, b) => b.n - a.n), (k) => 'SDG ' + k + ' · ' + (SDG[k] || ''));
bars($('region'), D.byRegion || [], (k) => k);

// weekly lines
(function weekly() {
  const el = $('weekly'), rows = D.weekly || [];
  const weeks = [...new Set(rows.map((r) => r.week))].sort();
  const srcs = Object.keys(SRC).filter((s) => rows.some((r) => r.source === s));
  $('wlegend').innerHTML = srcs.map((s) => '<span><i style="background:var(' + SRC[s].v + ')"></i>' + SRC[s].label + '</span>').join('');
  if (!weeks.length) { el.innerHTML = '<div class="muted">No data yet</div>'; return; }
  const W = 520, H = 200, L = 32, R = 10, T = 8, B = 22;
  const val = (s, w) => (rows.find((r) => r.source === s && r.week === w) || {}).n || 0;
  const max = Math.max(1, ...rows.map((r) => r.n));
  const x = (i) => L + (weeks.length === 1 ? (W - L - R) / 2 : i * (W - L - R) / (weeks.length - 1));
  const y = (v) => T + (H - T - B) * (1 - v / max);
  let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" role="img" aria-label="Weekly new items by source">';
  [0, 0.5, 1].forEach((f) => { const v = Math.round(max * f); svg += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + y(v) + '" y2="' + y(v) + '" stroke="var(--grid)"/><text x="' + (L - 6) + '" y="' + (y(v) + 4) + '" text-anchor="end">' + v + '</text>'; });
  weeks.forEach((w, i) => { if (i % Math.ceil(weeks.length / 6) === 0) svg += '<text x="' + x(i) + '" y="' + (H - 6) + '" text-anchor="middle">' + w.slice(5) + '</text>'; });
  srcs.forEach((s) => {
    svg += '<polyline fill="none" stroke="var(' + SRC[s].v + ')" stroke-width="2" stroke-linejoin="round" points="' + weeks.map((w, i) => x(i) + ',' + y(val(s, w))).join(' ') + '"/>';
    weeks.forEach((w, i) => { svg += '<circle cx="' + x(i) + '" cy="' + y(val(s, w)) + '" r="3" fill="var(' + SRC[s].v + ')" stroke="var(--surface)" stroke-width="2"/>'; });
  });
  svg += '<line id="xh" y1="' + T + '" y2="' + (H - B) + '" stroke="var(--muted)" stroke-dasharray="3 3" style="display:none"/><rect x="' + L + '" y="0" width="' + (W - L - R) + '" height="' + H + '" fill="transparent" id="hit"/></svg>';
  el.innerHTML = svg;
  const hit = el.querySelector('#hit'), xh = el.querySelector('#xh'), s = el.querySelector('svg');
  hit.onmousemove = (e) => {
    const r = s.getBoundingClientRect(); const px = (e.clientX - r.left) * W / r.width;
    let i = 0, best = 1e9; weeks.forEach((w, j) => { const d = Math.abs(x(j) - px); if (d < best) { best = d; i = j; } });
    xh.setAttribute('x1', x(i)); xh.setAttribute('x2', x(i)); xh.style.display = '';
    showTip(e, '<b>Week of ' + weeks[i] + '</b><br>' + srcs.map((k) => '<span class="src"><i style="background:var(' + SRC[k].v + ')"></i>' + SRC[k].label + ': ' + val(k, weeks[i]) + '</span>').join('<br>'));
  };
  hit.onmouseleave = () => { xh.style.display = 'none'; hideTip(); };
})();

// table
(D.bySource || []).forEach((s) => $('fsrc').insertAdjacentHTML('beforeend', '<option value="' + esc(s.k) + '">' + esc(SRC[s.k]?.label || s.k) + '</option>'));
(D.byDomain || []).forEach((d) => $('fdom').insertAdjacentHTML('beforeend', '<option value="' + esc(d.k) + '">' + esc(DOM[d.k] || d.k) + '</option>'));
let shown = 50;
function table() {
  const q = $('q').value.trim().toLowerCase(), fs = $('fsrc').value; domFilter = $('fdom').value;
  const list = (D.latest || []).filter((p) => (!fs || p.source === fs) && (!domFilter || p.domain === domFilter) &&
    (!q || [p.title, p.summary, p.owner].join(' ').toLowerCase().includes(q)));
  $('count').textContent = list.length + ' of ' + (D.latest || []).length + ' most recent projects';
  $('more').style.display = list.length > shown ? '' : 'none';
  $('rows').innerHTML = list.slice(0, shown).map((p) => '<tr><td><a href="' + esc(p.url) + '" target="_blank" rel="noopener">' + esc(p.title) + '</a>' +
    '<div class="s">' + esc(p.summary) + '</div><div class="s"><span class="src"><i style="background:var(' + (SRC[p.source]?.v || '--muted') + ')"></i>' + esc(SRC[p.source]?.label || p.source) + '</span>' +
    (p.owner ? ' · ' + esc(p.owner) : '') + (p.stars != null ? ' · ★ ' + p.stars : '') + (p.analyzed_by === 'llm' ? ' · LLM' : '') + '</div></td>' +
    '<td class="hide-sm"><span class="chip">' + esc(DOM[p.domain] || p.domain) + '</span><br>' + (p.sdgs || []).map((n) => '<span class="chip" title="' + esc(SDG[n]) + '">SDG ' + n + '</span>').join('') + '</td>' +
    '<td class="hide-sm">' + esc(p.region) + '</td><td style="white-space:nowrap">' + fmtDate(p.date) + '</td></tr>').join('') ||
    '<tr><td colspan="4" class="muted">No projects match. Run the “AI4SG · Collect & Analyze” workflow to fill the catalogue.</td></tr>';
}
$('more').onclick = () => { shown += 50; table(); };
$('q').oninput = () => { shown = 50; table(); }; $('fsrc').onchange = table; $('fdom').onchange = () => { table(); drawDomains(); };
$('reset').onclick = () => { $('q').value = ''; $('fsrc').value = ''; $('fdom').value = ''; table(); drawDomains(); };
table();
</script></body></html>`;

return [{ json: { body: html, contentType: 'text/html; charset=utf-8' } }];
